static void close_fd(int *fd) { if (*fd >= 0) close(*fd); }

void write_report(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return;
    __attribute__((cleanup(close_fd))) int owned = fd;  /* runs on every exit */

    if (emit(&owned) < 0) return;                       /* fd still closed here */
    ...                                                 /* and on the success path */
}                                                       /* close_fd(&owned) */

