int copy(const char *src, const char *dst) {
    int rc = -1, in = -1, out = -1;
    if ((in = open(src, O_RDONLY)) < 0)                goto done;
    if ((out = open(dst, O_WRONLY | O_CREAT, 0644)) < 0) goto done;
    rc = pump(in, out);              /* any failure jumps to done */
 done:                               /* single exit, reverse-order release */
    if (out >= 0) close(out);
    if (in >= 0) close(in);
    return rc;
}
